urlset:
{{ range .Data.Pages }}
{{- $priority := 0.3 -}}
{{- if .IsHome -}}
  {{- $priority = 1.0 -}}
{{- else if and (eq .Kind "page") (eq .Section "posts") -}}
  {{- $priority = 0.8 -}}
{{- end -}}

  {{ .Permalink }}
  {{ if not .Lastmod.IsZero }}{{ safeHTML ( .Lastmod.Format "2006-01-02T15:04:05-07:00" ) }}{{ end }}
  {{ with .Sitemap.ChangeFreq }}{{ . }}{{ end }}
  {{ $priority }}

{{ end }}
